/**
 * Standalone bridge boot harness.  tmp/ only — not repo source.
 *
 * The companion bridge has never been started. Everything so far is "it
 * compiles and the gates are green". This boots it against a THROWAWAY host.db
 * so the user's running Superset is never touched, then drives the cleartext
 * health path and the unauthenticated rejection paths.
 *
 * It does not pair, does not seal a request, and never writes to a terminal.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createDb } from "../packages/host-service/src/db";
import {
	SqliteTerminalAgentBindingPersistence,
	TerminalAgentStore,
} from "../packages/host-service/src/terminal-agents";
import { startCompanionBridgeIfEnabled } from "../packages/host-service/src/companion";

const REPO = join(import.meta.dirname, "..");
const scratch = mkdtempSync(join(tmpdir(), "companion-boot-"));

// The bridge reads its real config from ~/.superset/companion. Point HOME-derived
// paths at a scratch dir so nothing here can disturb the real device keys.
process.env.SUPERSET_COMPANION_BRIDGE = "1";
process.env.SUPERSET_HOME_DIR = scratch;

let bridge: Awaited<ReturnType<typeof startCompanionBridgeIfEnabled>> = null;

async function probe(label: string, url: string, init?: RequestInit) {
	try {
		const res = await fetch(url, init);
		const body = await res.text();
		console.log(
			`  ${label.padEnd(34)} ${res.status} ${body.slice(0, 110).replace(/\s+/g, " ")}`,
		);
	} catch (error) {
		console.log(`  ${label.padEnd(34)} FETCH-FAILED ${(error as Error).message}`);
	}
}

async function main() {
	const dbPath = join(scratch, "host.db");
	console.log(`scratch: ${scratch}`);

	const db = createDb(dbPath, join(REPO, "packages/host-service/drizzle"));
	const terminalAgentStore = new TerminalAgentStore(
		new SqliteTerminalAgentBindingPersistence(db),
	);
	console.log("db + agent store constructed");

	const started = Date.now();
	bridge = await startCompanionBridgeIfEnabled({
		hostDbPath: dbPath,
		db,
		terminalAgentStore,
	});
	console.log(
		bridge === null
			? "BRIDGE RETURNED NULL (gate closed — SUPERSET_COMPANION_BRIDGE unset?)"
			: `BRIDGE STARTED in ${Date.now() - started}ms`,
	);
	if (bridge === null) return;

	const base = "http://127.0.0.1:47610";
	console.log("\n--- unauthenticated probes ---");
	await probe("GET /v1/ping", `${base}/v1/ping`);
	await probe("GET / (unknown path)", `${base}/`);
	await probe("GET /v1/tree (needs seal)", `${base}/v1/tree`);
	await probe("POST /v1/answer garbage", `${base}/v1/answer`, {
		method: "POST",
		body: "not-a-sealed-envelope",
	});
	await probe("POST /v1/answer 4MB body", `${base}/v1/answer`, {
		method: "POST",
		body: "A".repeat(4 * 1024 * 1024),
	});
	await probe("POST /v1/answer empty", `${base}/v1/answer`, { method: "POST" });

	console.log("\n--- is it still alive after that? ---");
	await probe("GET /v1/ping (again)", `${base}/v1/ping`);
}

main()
	.catch((error) => {
		console.error("\nHARNESS FAILED:");
		console.error(error);
		process.exitCode = 1;
	})
	.finally(async () => {
		if (bridge !== null) {
			await bridge.stop("harness").catch(() => {});
			console.log("\nbridge stopped cleanly");
		}
		rmSync(scratch, { recursive: true, force: true });
	});

