// ---------------------------------------------------------------------------
// 5. PRE-WITNESS FILE (no seq, no witness) -> believed exactly once
// ---------------------------------------------------------------------------
{
	const d = await freshDir();
	// Exactly what the previous build wrote: version 1, no `seq`, no witness.
	await writeFile(
		filePath(d),
		`${JSON.stringify(
			{ version: 1, coverageSinceMs: t0, records: [confirmed] },
			null,
			"\t",
		)}\n`,
		"utf8",
	);
	const c = collector();
	const restartMs = t0 + HOUR;
	const s = await createAttemptStore({
		dir: d,
		generation: GEN_A,
		nowMs: restartMs,
		log: c.log,
	});
	check(
		"5a legacy unwitnessed file is trusted (upgrade path), record kept",
		c.degraded().length === 0 &&
			s.recordsSinceMs(restartMs) === t0 &&
			s.get(base.requestId)?.status === "confirmed",
		`recordsSinceMs=${s.recordsSinceMs(restartMs)} degraded=${JSON.stringify(c.degraded())}`,
	);
	const file = await readJson(filePath(d));
	const wit = await readJson(witPath(d));
	check(
		"5b and it is witnessed from this mount onwards",
		file.seq === 1 && wit.seq === 1 && wit.generation === GEN_A,
		`file.seq=${file.seq} witness=${JSON.stringify(wit)}`,
	);
}

