/**
 * tmp/ only. Tests the claim in crypto.ts:1025-1027 that Node cannot open a
 * Windows directory handle — the stated REASON syncDirectory is a no-op on
 * win32, which is the root cause (ATTEMPT-WITNESS) exists to work around.
 *
 * A Sol review reported that an `r+` directory handle syncs successfully while a
 * read-only one gives EPERM. If that holds under BUN (the host-service runtime,
 * not just Node) then syncDirectory could stop being a no-op and the whole
 * cross-file rename-ordering assumption stops being load-bearing.
 *
 * IMPORTANT: this proves only whether the CALL SUCCEEDS. It does NOT prove NTFS
 * flushed the directory metadata log — that needs a real power-cut test. Do not
 * change syncDirectory on the strength of this alone.
 */
import { mkdtempSync, openSync, closeSync, fsyncSync, writeFileSync, renameSync, rmSync } from "node:fs";
import { open } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const dir = mkdtempSync(join(tmpdir(), "dirsync-"));
console.log(`runtime: ${typeof Bun !== "undefined" ? `Bun ${Bun.version}` : `Node ${process.version}`}  platform: ${process.platform} ${process.arch}`);
console.log(`dir: ${dir}\n`);

function attempt(label: string, flags: string) {
	let fd: number | null = null;
	try {
		fd = openSync(dir, flags);
	} catch (error) {
		console.log(`  ${label.padEnd(22)} open  FAILED  ${(error as NodeJS.ErrnoException).code}`);
		return;
	}
	try {
		fsyncSync(fd);
		console.log(`  ${label.padEnd(22)} open OK, fsync OK`);
	} catch (error) {
		console.log(`  ${label.padEnd(22)} open OK, fsync FAILED  ${(error as NodeJS.ErrnoException).code}`);
	} finally {
		try {
			closeSync(fd);
		} catch {
			/* the close itself can fail on a directory handle; not the question here */
		}
	}
}

console.log("--- sync openSync + fsyncSync on the DIRECTORY ---");
for (const [label, flags] of [
	["r (read-only)", "r"],
	["r+", "r+"],
	["a", "a"],
	["w", "w"],
] as const) {
	attempt(label, flags);
}

console.log("\n--- promises API, r+ then handle.sync() ---");
try {
	const h = await open(dir, "r+");
	try {
		await h.sync();
		console.log("  fsPromises r+ + sync()   OK");
	} catch (error) {
		console.log(`  fsPromises r+ + sync()   FAILED  ${(error as NodeJS.ErrnoException).code}`);
	} finally {
		await h.close().catch(() => {});
	}
} catch (error) {
	console.log(`  fsPromises open r+       FAILED  ${(error as NodeJS.ErrnoException).code}`);
}

// Does it still work when the directory has just had a rename in it? That is the
// only state syncDirectory would ever be called in.
console.log("\n--- after a real tmp -> rename in that directory ---");
writeFileSync(join(dir, "x.tmp"), "payload\n");
renameSync(join(dir, "x.tmp"), join(dir, "x.json"));
attempt("r+ post-rename", "r+");

rmSync(dir, { recursive: true, force: true });
console.log("\nNOTE: success here means the CALL succeeds, NOT that NTFS persisted the");
console.log("directory entry. A syncDirectory that appears to work but does not would be");
console.log("WORSE than an honest no-op, because everything above it stops compensating.");

