/**
 * tmp/ only. Direct verification of the B1 fix: a witness that cannot be WRITTEN
 * must degrade coverage, not stop the bridge from starting.
 *
 * Does not read another probe's pass/fail labels — it asserts the two things that
 * actually matter: createAttemptStore RESOLVES, and it reports the degrade.
 */
import { mkdirSync, mkdtempSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createAttemptStore } from "../packages/host-service/src/companion/answer";

const GEN = "AAAAAAAAAAAAAAAAAAAAAA";
let failures = 0;

function check(label: string, ok: boolean, detail: string) {
	if (!ok) failures += 1;
	console.log(`${ok ? "PASS" : "FAIL"}  ${label} :: ${detail}`);
}

// A DIRECTORY sitting at the witness path is the cleanest portable way to make
// every write to it fail: the rename cannot replace a directory.
{
	const dir = mkdtempSync(join(tmpdir(), "b1-dir-"));
	mkdirSync(join(dir, "answer-attempts-witness.json"));
	const events: Record<string, unknown>[] = [];
	let started = false;
	let thrown: unknown = null;
	try {
		const s = await createAttemptStore({
			dir,
			generation: GEN,
			nowMs: 1_000_000_000_000,
			log: (e) => events.push(e),
		});
		started = true;
		check(
			"1c the store SERVES after the fault (get on an unknown id is null, not a throw)",
			s.get("11111111-2222-4333-8444-555555555555") === null,
			"get() returned null",
		);
		check(
			"1d coverage is narrowed to this mount",
			s.recordsSinceMs(1_000_000_000_000) === 1_000_000_000_000,
			`recordsSinceMs=${s.recordsSinceMs(1_000_000_000_000)}`,
		);
	} catch (error) {
		thrown = error;
	}
	check(
		"1a an unwritable witness does NOT stop the store from opening",
		started && thrown === null,
		thrown === null ? "resolved" : `THREW: ${(thrown as Error).message}`,
	);
	const degraded = events.filter(
		(e) => e.event === "companion.answer.attempt_coverage_degraded",
	);
	check(
		"1b and the fault is reported as a degrade, naming the write",
		degraded.length >= 1 &&
			String(degraded[0]?.why ?? "").includes("could not be written"),
		`why=${JSON.stringify(degraded[0]?.why ?? null)}`,
	);
	check(
		"1e the attempts file itself was still written",
		existsSync(join(dir, "answer-attempts.json")),
		`exists=${existsSync(join(dir, "answer-attempts.json"))}`,
	);
	rmSync(dir, { recursive: true, force: true });
}

console.log(
	failures === 0
		? "\nB1 CLOSED: an unwritable witness degrades and the bridge still starts"
		: `\n${failures} CHECK(S) FAILED — B1 is not closed`,
);
process.exitCode = failures === 0 ? 0 : 1;

