input.content:
/**
 * tmp/ only. Proves (STORE-CLOSED): after `close()`, a rewrite that a stopped
 * bridge's detached maintenance already queued can no longer reach the file.
 *
 * This is the property that lets the teardown drain be BOUNDED. If the guard did
 * not hold, giving up on a slow drain would re-open the clobbering the drain was
 * added to prevent — so it is worth proving rather than assuming.
 */
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createAttemptStore } from "../packages/host-service/src/companion/answer";

const GEN = "AAAAAAAAAAAAAAAAAAAAAA";
const t0 = 1_000_000_000_000;
let failures = 0;

function check(label: string, ok: boolean, detail: string) {
	if (!ok) failures += 1;
	console.log(`${ok ? "PASS" : "FAIL"}  ${label} :: ${detail}`);
}

const record = (id: string) => ({
	requestId: `1111111${id}-2222-4333-8444-555555555555`,
	questionId: "q0000000000000000000000",
	deviceId: "d0000000000000000000000",
	surface: "phone" as const,
	leaseId: "l000000000000000",
	startedAtMs: t0,
	status: "confirmed" as const,
	resolvedAtMs: t0 + 5,
	failureCode: null,
	guardsPassed: ["transcript" as const, "screen" as const],
});

const dir = mkdtempSync(join(tmpdir(), "store-closed-"));
const filePath = join(dir, "answer-attempts.json");
const read = () => JSON.parse(readFileSync(filePath, "utf8"));

const store = await createAttemptStore({
	dir,
	generation: GEN,
	nowMs: t0,
	log: () => {},
});
await store.put(record("a"));
const before = read();

// The stale writer: a put queued, then the bridge tears down before it runs.
// `close()` lands while that rewrite is still sitting in the serialisation tail.
const queued = store.put(record("b"));
store.close();
await queued;

const after = read();
check(
	"1a the file is untouched by a rewrite that raced close()",
	after.seq === before.seq && after.records.length === before.records.length,
	`seq ${before.seq} -> ${after.seq}, records ${before.records.length} -> ${after.records.length}`,
);
check(
	"1b the counter did not move (a lowered mark is what corrupted the file before)",
	after.seq === before.seq,
	`seq=${after.seq}`,
);

// Everything after close is a no-op too, including the maintenance path that
// actually caused the original bug.
const pruned = await store.prune(t0 + 30 * 3_600_000);
const afterPrune = read();
check(
	"1c prune after close writes nothing",
	afterPrune.seq === before.seq &&
		afterPrune.records.length === before.records.length,
	`pruned=${pruned} seq=${afterPrune.seq} records=${afterPrune.records.length}`,
);
check(
	"1d close() is idempotent",
	(() => {
		store.close();
		store.close();
		return true;
	})(),
	"called three times, no throw",
);
check(
	"1e reads still work after close (only writes are refused)",
	store.get(record("a").requestId)?.status === "confirmed",
	`get=${store.get(record("a").requestId)?.status}`,
);

rmSync(dir, { recursive: true, force: true });
console.log(
  failures === 0
    ? "\nSTORE-CLOSED holds: a stale writer cannot reach the file after close()"
    : `\n${failures} CHECK(S) FAILED`,
);
process.exitCode = failures === 0 ? 0 : 1;

