/**
 * Probe: prune() vs recordsSinceMs() under wall-clock regression.
 *
 * Claim under test: prune(nowMs) irreversibly drops a record, but the
 * published window floor `nowMs - retentionMs` is recomputed from the caller's
 * CURRENT clock. If the clock steps backward after a prune, the window can
 * re-cover the pruned record's startedAtMs -> get() === null inside the
 * published window -> the store's stated invariant ("for every answer attempt
 * it admitted whose attempt began at or after this instant, a record exists")
 * is violated.
 */
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createAttemptStore } from "../packages/host-service/src/companion/answer.ts";

const HOUR = 3_600_000;
const GEN_A = "AAAAAAAAAAAAAAAAAAAAAA";
const t0 = 1_000_000_000_000;

const results: string[] = [];
function check(name: string, ok: boolean, detail: string) {
	results.push(`${ok ? "PASS" : "FAIL"}  ${name} :: ${detail}`);
	if (!ok) process.exitCode = 1;
}

const record = {
	requestId: "11111111-2222-4333-8444-555555555555",
	questionId: "q0000000000000000000000",
	deviceId: "d0000000000000000000000",
	surface: "phone" as const,
	leaseId: "l000000000000000",
	startedAtMs: t0,
	resolvedAtMs: t0 + 500,
	failureCode: null,
	status: "confirmed" as const,
	guardsPassed: ["transcript" as const, "screen" as const],
};

// --- Variant 1: in-process prune, then clock regression ---------------------
{
	const d = await mkdtemp(join(tmpdir(), "attempt-prune-clock-"));
	const s = await createAttemptStore({
		dir: d,
		generation: GEN_A,
		nowMs: t0,
		log: () => {},
	});
	await s.put(record);

	// Timer fires with a sane clock: record is 25h old, retention 24h -> drop.
	const dropped = await s.prune(t0 + 25 * HOUR);
	check("1a prune dropped the 25h-old record", dropped === 1, `dropped=${dropped}`);

	// Clock steps back 2h (NTP correction / VM resume). Status read arrives.
	const readNow = t0 + 23 * HOUR;
	const win = s.recordsSinceMs(readNow);
	const got = s.get(record.requestId);
	check(
		"1b window now claims coverage over the pruned record (win <= startedAtMs) while get() is null",
		win <= record.startedAtMs && got === null,
		`recordsSinceMs=${win} startedAtMs=${record.startedAtMs} get=${JSON.stringify(got)}`,
	);
}

// --- Variant 2: hydration retention filter, restart, regression -------------
// Record dropped at REMOUNT (mount clock says it is 25h old, drop is baked
// into the initial persist), then a later read with a clock 2h earlier.
{
	const d = await mkdtemp(join(tmpdir(), "attempt-prune-clock-"));
	const s1 = await createAttemptStore({
		dir: d,
		generation: GEN_A,
		nowMs: t0,
		log: () => {},
	});
	await s1.put(record);

	const s2 = await createAttemptStore({
		dir: d,
		generation: GEN_A,
		nowMs: t0 + 25 * HOUR, // hydration filter drops the record
		log: () => {},
	});
	check(
		"2a remount 25h later hydration-dropped the record",
		s2.get(record.requestId) === null,
		`get=${JSON.stringify(s2.get(record.requestId))}`,
	);
	const win = s2.recordsSinceMs(t0 + 23 * HOUR); // clock stepped back 2h
	check(
		"2b same store publishes a window covering the dropped record",
		win <= record.startedAtMs,
		`recordsSinceMs=${win} startedAtMs=${record.startedAtMs}`,
	);
}

console.log(results.join("\n"));

