/**
 * tmp/ only. Proves (PRUNE-FLOOR) survives a restart and never moves backwards.
 *
 * The in-memory half is already covered by attempt-prune-clock-probe.ts. What
 * that probe cannot show is the part the fix actually depends on: the remembered
 * boundary is DURABLE, so a clock that moves between mounts cannot re-expose
 * records an earlier mount already dropped.
 */
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createAttemptStore } from "../packages/host-service/src/companion/answer";

const GEN = "AAAAAAAAAAAAAAAAAAAAAA";
const HOUR = 3_600_000;
const t0 = 1_000_000_000_000;
let failures = 0;

function check(label: string, ok: boolean, detail: string) {
	if (!ok) failures += 1;
	console.log(`${ok ? "PASS" : "FAIL"}  ${label} :: ${detail}`);
}

const record = {
	requestId: "11111111-2222-4333-8444-555555555555",
	questionId: "q0000000000000000000000",
	deviceId: "d0000000000000000000000",
	surface: "phone" as const,
	leaseId: "l000000000000000",
	startedAtMs: t0,
	status: "confirmed" as const,
	resolvedAtMs: t0 + 5,
	failureCode: null,
	guardsPassed: ["transcript" as const, "screen" as const],
};

const dir = mkdtempSync(join(tmpdir(), "prune-floor-"));
const open = (nowMs: number) =>
	createAttemptStore({ dir, generation: GEN, nowMs, log: () => {} });
const read = () => JSON.parse(readFileSync(join(dir, "answer-attempts.json"), "utf8"));

// Mount 1: record it, then prune past its retention so the boundary is crossed.
const s1 = await open(t0);
await s1.put(record);
const dropped = await s1.prune(t0 + 25 * HOUR);
s1.close();

const onDisk = read();
check(
	"1a the crossed boundary was PERSISTED, not just held in memory",
	onDisk.prunedThroughMs === t0 + 25 * HOUR - 24 * HOUR,
	`prunedThroughMs=${onDisk.prunedThroughMs} expected=${t0 + HOUR} dropped=${dropped}`,
);

// Mount 2 with the clock STEPPED BACK two hours. Without a durable floor this
// mount would recompute `now - retention` and reach behind the dropped record.
const s2 = await open(t0 + 23 * HOUR);
const win = s2.recordsSinceMs(t0 + 23 * HOUR);
check(
	"1b a NEW mount under a rewound clock still excludes the dropped record",
	win > record.startedAtMs,
	`recordsSinceMs=${win} startedAtMs=${record.startedAtMs}`,
);
check(
	"1c and the record really is gone, so the window is not merely cautious",
	s2.get(record.requestId) === null,
	`get=${JSON.stringify(s2.get(record.requestId))}`,
);

// Rise-only: a prune at an EARLIER boundary must not lower the remembered floor.
const before = read().prunedThroughMs;
await s2.prune(t0 + 2 * HOUR);
const after = read().prunedThroughMs;
check(
	"1d an earlier prune cannot lower the floor",
	after >= before,
	`before=${before} after=${after}`,
);
s2.close();

// A pre-(PRUNE-FLOOR) file has no field at all: it must load, not quarantine.
const legacyDir = mkdtempSync(join(tmpdir(), "prune-floor-legacy-"));
await Bun.write(
	join(legacyDir, "answer-attempts.json"),
	`${JSON.stringify({ version: 1, coverageSinceMs: t0, seq: 1, records: [record] })}\n`,
);
const legacyEvents: Record<string, unknown>[] = [];
const s3 = await createAttemptStore({
	dir: legacyDir,
	generation: GEN,
	nowMs: t0 + 60_000,
	log: (e) => legacyEvents.push(e),
});
check(
	"2a a file written before this field loads and keeps its record",
	s3.get(record.requestId)?.status === "confirmed" &&
		!legacyEvents.some((e) => e.event === "companion.answer.attempt_store_corrupt"),
	`get=${s3.get(record.requestId)?.status} corrupt=${legacyEvents.some((e) => e.event === "companion.answer.attempt_store_corrupt")}`,
);
s3.close();

rmSync(dir, { recursive: true, force: true });
rmSync(legacyDir, { recursive: true, force: true });
console.log(
	failures === 0
		? "\nPRUNE-FLOOR holds: the boundary is durable, rise-only, and backward-compatible"
		: `\n${failures} CHECK(S) FAILED`,
);
process.exitCode = failures === 0 ? 0 : 1;

