/**
 * tmp/ only. Proves the cross-field disk rule: a record that says the answer
 * landed but not WHEN is refused, and a coherent file still loads.
 *
 * Field-by-field validation accepted `confirmed` with a null `resolvedAtMs`, and
 * the status handler then served it verbatim as `known: true, confirmed` — leaving
 * the client to invent a policy for a shape the server should never have emitted.
 */
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createAttemptStore } from "../packages/host-service/src/companion/answer";

const GEN = "AAAAAAAAAAAAAAAAAAAAAA";
const t0 = 1_000_000_000_000;
let failures = 0;

function check(label: string, ok: boolean, detail: string) {
	if (!ok) failures += 1;
	console.log(`${ok ? "PASS" : "FAIL"}  ${label} :: ${detail}`);
}

const base = {
	requestId: "11111111-2222-4333-8444-555555555555",
	questionId: "q0000000000000000000000",
	deviceId: "d0000000000000000000000",
	surface: "phone" as const,
	leaseId: "l000000000000000",
	startedAtMs: t0,
	guardsPassed: ["transcript", "screen"],
};

async function load(record: Record<string, unknown>, label: string) {
	const dir = mkdtempSync(join(tmpdir(), "xfield-"));
	writeFileSync(
		join(dir, "answer-attempts.json"),
		`${JSON.stringify({ version: 1, coverageSinceMs: t0, seq: 1, prunedThroughMs: 0, records: [record] })}\n`,
		"utf8",
	);
	const events: Record<string, unknown>[] = [];
	const store = await createAttemptStore({
		dir,
		generation: GEN,
		nowMs: t0 + 60_000,
		log: (e) => events.push(e),
	});
	const quarantined = events.some(
		(e) => e.event === "companion.answer.attempt_store_corrupt",
	);
	const served = store.get(base.requestId) !== null;
	store.close();
	rmSync(dir, { recursive: true, force: true });
	return { quarantined, served, label };
}

// 1. confirmed with no resolvedAtMs — the shape that used to be served as truth.
{
	const r = await load(
		{ ...base, status: "confirmed", resolvedAtMs: null, failureCode: null },
		"confirmed/null",
	);
	check(
		"1a confirmed with a null resolvedAtMs is REFUSED, not served",
		r.quarantined && !r.served,
		`quarantined=${r.quarantined} served=${r.served}`,
	);
}

// 2. failed with no failureCode — the mirror case.
{
	const r = await load(
		{ ...base, status: "failed", resolvedAtMs: null, failureCode: null },
		"failed/null",
	);
	check(
		"1b failed with a null failureCode is REFUSED",
		r.quarantined && !r.served,
		`quarantined=${r.quarantined} served=${r.served}`,
	);
}

// 3. The shapes this bridge actually writes must still load. If any of these
//    quarantined, the rule would be a self-inflicted outage rather than a guard.
{
	const ok1 = await load(
		{ ...base, status: "confirmed", resolvedAtMs: t0 + 5, failureCode: null },
		"confirmed/stamped",
	);
	const ok2 = await load(
		{ ...base, status: "failed", resolvedAtMs: null, failureCode: "guard_failed" },
		"failed/coded",
	);
	const ok3 = await load(
		{ ...base, status: "in_flight", resolvedAtMs: null, failureCode: null },
		"in_flight",
	);
	const ok4 = await load(
		{ ...base, status: "unconfirmed", resolvedAtMs: null, failureCode: null },
		"unconfirmed",
	);
	for (const r of [ok1, ok2, ok3, ok4]) {
		check(
			`1c a record this bridge writes still loads (${r.label})`,
			!r.quarantined && r.served,
			`quarantined=${r.quarantined} served=${r.served}`,
		);
	}
}

console.log(
	failures === 0
		? "\nCROSS-FIELD rule holds: incoherent records refused, real ones untouched"
		: `\n${failures} CHECK(S) FAILED`,
);
process.exitCode = failures === 0 ? 0 : 1;

