$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$root = 'C:\Users\khair\dev-tools'
$jdkDir = Join-Path $root 'jdk-21'
$sdkDir = Join-Path $root 'android-sdk'
New-Item -ItemType Directory -Force -Path $root | Out-Null

# ---- JDK 21 (native Windows ARM64, portable zip, no admin) ----
if (-not (Test-Path (Join-Path $jdkDir 'bin\java.exe'))) {
  Write-Output "== downloading Microsoft OpenJDK 21 (win-aarch64) =="
  $jdkZip = Join-Path $env:TEMP 'msjdk21-aarch64.zip'
  Invoke-WebRequest -Uri 'https://aka.ms/download-jdk/microsoft-jdk-21-windows-aarch64.zip' -OutFile $jdkZip
  $tmp = Join-Path $env:TEMP 'jdkx'
  if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
  Expand-Archive -Path $jdkZip -DestinationPath $tmp -Force
  $inner = Get-ChildItem $tmp -Directory | Select-Object -First 1
  if (Test-Path $jdkDir) { Remove-Item -Recurse -Force $jdkDir }
  Move-Item $inner.FullName $jdkDir
  Remove-Item -Recurse -Force $tmp, $jdkZip -ErrorAction SilentlyContinue
} else {
  Write-Output "== JDK already present =="
}

$env:JAVA_HOME = $jdkDir
$env:PATH = "$jdkDir\bin;$env:PATH"
& "$jdkDir\bin\java.exe" -version 2>&1 | ForEach-Object { Write-Output "java: $_" }

# ---- Android commandline-tools ----
$cmdlineHome = Join-Path $sdkDir 'cmdline-tools\latest'
if (-not (Test-Path (Join-Path $cmdlineHome 'bin\sdkmanager.bat'))) {
  Write-Output "== downloading Android commandline-tools =="
  $clZip = Join-Path $env:TEMP 'android-cmdline-tools.zip'
  Invoke-WebRequest -Uri 'https://dl.google.com/android/repository/commandlinetools-win-13114758_latest.zip' -OutFile $clZip
  $tmp2 = Join-Path $env:TEMP 'clx'
  if (Test-Path $tmp2) { Remove-Item -Recurse -Force $tmp2 }
  Expand-Archive -Path $clZip -DestinationPath $tmp2 -Force
  New-Item -ItemType Directory -Force -Path (Split-Path $cmdlineHome -Parent) | Out-Null
  if (Test-Path $cmdlineHome) { Remove-Item -Recurse -Force $cmdlineHome }
  Move-Item (Join-Path $tmp2 'cmdline-tools') $cmdlineHome
  Remove-Item -Recurse -Force $tmp2, $clZip -ErrorAction SilentlyContinue
} else {
  Write-Output "== cmdline-tools already present =="
}

$env:ANDROID_HOME = $sdkDir
$env:ANDROID_SDK_ROOT = $sdkDir
$sdkmanager = Join-Path $cmdlineHome 'bin\sdkmanager.bat'

Write-Output "== accepting licenses =="
$yes = ("y`n" * 60)
$yes | & $sdkmanager --sdk_root="$sdkDir" --licenses 2>&1 | Select-Object -Last 5 | ForEach-Object { Write-Output "lic: $_" }

Write-Output "== installing platform-tools, platform 36, build-tools =="
& $sdkmanager --sdk_root="$sdkDir" "platform-tools" "platforms;android-36" "build-tools;36.0.0" 2>&1 |
  Select-Object -Last 12 | ForEach-Object { Write-Output "sdk: $_" }

# ---- persist to user environment (no admin needed) ----
[Environment]::SetEnvironmentVariable('JAVA_HOME', $jdkDir, 'User')
[Environment]::SetEnvironmentVariable('ANDROID_HOME', $sdkDir, 'User')
[Environment]::SetEnvironmentVariable('ANDROID_SDK_ROOT', $sdkDir, 'User')
$userPath = [Environment]::GetEnvironmentVariable('PATH', 'User')
$add = @("$jdkDir\bin", "$sdkDir\platform-tools", "$cmdlineHome\bin")
foreach ($p in $add) {
  if ($userPath -notlike "*$p*") { $userPath = "$userPath;$p" }
}
[Environment]::SetEnvironmentVariable('PATH', $userPath, 'User')

Write-Output "== DONE =="
Write-Output "JAVA_HOME=$jdkDir"
Write-Output "ANDROID_HOME=$sdkDir"
& "$jdkDir\bin\java.exe" -version 2>&1 | ForEach-Object { Write-Output "verify-java: $_" }
if (Test-Path (Join-Path $sdkDir 'platform-tools\adb.exe')) { Write-Output "verify-adb: present" } else { Write-Output "verify-adb: MISSING" }
if (Test-Path (Join-Path $sdkDir 'platforms\android-36')) { Write-Output "verify-platform36: present" } else { Write-Output "verify-platform36: MISSING" }

