import java.util.Properties

plugins {
    alias(libs.plugins.android.application)
    alias(libs.plugins.kotlin.android)
    alias(libs.plugins.kotlin.compose)
    alias(libs.plugins.kotlin.serialization)
    alias(libs.plugins.ksp)
    alias(libs.plugins.google.services)
}

// Release signing lives OUTSIDE this repo, beside the FCM and Cloudflare secrets.
// Override with -PsigningPropertiesFile=... or SUPERSET_COMPANION_SIGNING.
val signingPropertiesPath: String =
    (findProperty("signingPropertiesFile") as String?)
        ?: System.getenv("SUPERSET_COMPANION_SIGNING")
        ?: "${System.getProperty("user.home")}/.superset/companion/keystore/signing.properties"

val signingProperties: Properties? = file(signingPropertiesPath)
    .takeIf { it.isFile }
    ?.let { f -> Properties().apply { f.inputStream().use { load(it) } } }

android {
    namespace = "family.khaira.supersetcompanion"
    compileSdk = 36

    defaultConfig {
        // MUST be identical to app-watch. The Wear Data Layer silently delivers
        // nothing between two apps whose applicationId or signing key differ —
        // no error, no callback, just silence.
        applicationId = "family.khaira.supersetcompanion"
        minSdk = 33
        targetSdk = 36
        versionCode = 1
        versionName = "0.1.0"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    signingConfigs {
        if (signingProperties != null) {
            create("release") {
                storeFile = file(signingProperties.getProperty("storeFile"))
                storePassword = signingProperties.getProperty("storePassword")
                keyAlias = signingProperties.getProperty("keyAlias")
                keyPassword = signingProperties.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            signingConfig = signingConfigs.findByName("release")
                ?: throw GradleException(
                    "Release signing is not configured: $signingPropertiesPath is missing. " +
                        "app-phone and app-watch must be signed with the SAME key or the Data Layer " +
                        "silently fails. Generate it or point -PsigningPropertiesFile at it."
                )
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
    }
}

dependencies {
    implementation(project(":core"))

    implementation(libs.androidx.core.ktx)
    implementation(libs.androidx.core.splashscreen)
    implementation(libs.androidx.activity.compose)
    implementation(libs.androidx.lifecycle.runtime.ktx)
    implementation(libs.androidx.lifecycle.runtime.compose)
    implementation(libs.androidx.lifecycle.viewmodel.compose)
    implementation(libs.androidx.lifecycle.process)

    implementation(platform(libs.androidx.compose.bom))
    implementation(libs.androidx.compose.ui)
    implementation(libs.androidx.compose.ui.graphics)
    implementation(libs.androidx.compose.ui.tooling.preview)
    implementation(libs.androidx.compose.material3)
    implementation(libs.androidx.compose.material.icons.extended)

    // Home and chat live in ONE adaptive scaffold: the Fold's inner screen shows both
    // panes, the cover screen shows one. Selection survives folding via saved state.
    implementation(libs.androidx.adaptive)
    implementation(libs.androidx.adaptive.layout)
    implementation(libs.androidx.adaptive.navigation)
    implementation(libs.androidx.navigation.compose)

    implementation(libs.androidx.room.runtime)
    implementation(libs.androidx.room.ktx)
    ksp(libs.androidx.room.compiler)
    implementation(libs.androidx.work.runtime.ktx)
    implementation(libs.androidx.datastore.preferences)

    implementation(libs.androidx.security.crypto)
    // Free-text sends require biometric confirmation; option taps do not.
    implementation(libs.androidx.biometric)

    // Phone <-> watch. Also carries BridgingManager notification suppression, so the
    // watch shows its own uncapped screen instead of a 1024-char-clamped bridge copy.
    implementation(libs.play.services.wearable)

    // Push wakes the phone on red. Payload is opaque ids only.
    implementation(platform(libs.firebase.bom))
    implementation(libs.firebase.messaging)

    // QR pairing: the code sits in the URL fragment so it never reaches a server.
    implementation(libs.mlkit.barcode.scanning)
    implementation(libs.camera.core)
    implementation(libs.camera.camera2)
    implementation(libs.camera.lifecycle)
    implementation(libs.camera.view)

    implementation(libs.kotlinx.coroutines.android)
    implementation(libs.kotlinx.serialization.json)

    debugImplementation(libs.androidx.compose.ui.tooling)
    debugImplementation(libs.androidx.compose.ui.test.manifest)

    testImplementation(libs.junit)
    testImplementation(libs.kotlinx.coroutines.test)
    androidTestImplementation(libs.androidx.test.ext.junit)
    androidTestImplementation(libs.androidx.test.espresso.core)
    androidTestImplementation(platform(libs.androidx.compose.bom))
    androidTestImplementation(libs.androidx.compose.ui.test.junit4)
}

