/** §11.5 — a READ. Safe to retry and poll. It is what replaces a write retry. */
export interface AnswerStatusResponse {
	requestId: RequestId;
	/** false => the bridge never saw this requestId; the client reports "not sent". */
	known: boolean;
	/**
	 * `in_flight` is NOT terminal: the lease is held and keystrokes are being
	 * typed into the picker right now. §11.6 defines that as `pending` on the
	 * client and the client must POLL, never conclude.
	 *
	 * (ANSWER-INFLIGHT) It exists because the attempt record used to be written
	 * only AFTER the injection returned, so for up to `LOCK_WAIT_TIMEOUT_MS +
	 * SEQUENCE_DEADLINE_MS` (~15 s) this endpoint answered `known: false` —
	 * documented and rendered as "not sent" — for an answer that was actively
	 * landing. That is the one window §11.5 exists to cover, and it lied in it.
	 * Do NOT collapse this into `unconfirmed`: the client treats `unconfirmed`
	 * as terminal.
	 */
	status: "confirmed" | "failed" | "unconfirmed" | "in_flight" | "unknown";
	questionId: QuestionId | null;
	resolvedAtMs: EpochMs | null;
	/** A §10 code when `status === "failed"`. */
	failureCode: ErrorCode | null;
}

