async function main() {
	const dbPath = join(scratch, "host.db");
	console.log(`scratch: ${scratch}`);

	// Copy ONLY the two credential files the bridge requires into the scratch
	// tree. Everything the bridge then writes — the state anchor, the send
	// witness, devices.json — lands in scratch and dies with it, so a boot test
	// can never disturb the real device keys under ~/.superset/companion.
	const realDir = join(homedir(), ".superset", "companion");
	mkdirSync(join(scratch, "companion"), { recursive: true });
	for (const f of ["cloudflare-access.json", "fcm-service-account.json"]) {
		const src = join(realDir, f);
		if (!existsSync(src)) {
			console.log(`MISSING real config: ${src} — cannot boot`);
			return;
		}
		copyFileSync(src, join(scratch, "companion", f));
	}
	console.log("real credentials copied into scratch (originals untouched)");

	const db = createDb(dbPath, join(REPO, "packages/host-service/drizzle"));
	const terminalAgentStore = new TerminalAgentStore(
		new SqliteTerminalAgentBindingPersistence(db),
	);
	console.log("db + agent store constructed");

	const started = Date.now();
	bridge = await startCompanionBridgeIfEnabled({
		hostDbPath: dbPath,
		db,
		terminalAgentStore,
	});
	console.log(
		bridge === null
			? "BRIDGE IS NULL — start() threw and was swallowed; see the error above"
			: `BRIDGE STARTED in ${Date.now() - started}ms`,
	);
	if (bridge === null) return;

