/**
 * A REAL better-sqlite3 stand-in, backed by Bun's built-in SQLite.
 *
 * NOT the published package, and not the empty stub this replaced. That stub
 * answered every query with nothing, which meant no database-backed path in the
 * bridge had ever been executed on this machine — the agent tree, the transcript
 * reader, and (the reason this exists) the SQLite-backed answer ledger.
 *
 * `better-sqlite3` needs a compiled win-arm64 binding that only the CI build
 * produces. Bun ships SQLite in-process, so the API surface drizzle and the
 * host-service actually use can be mapped onto it and the real SQL runs: real
 * tables, real transactions, real `changes` counts, real constraint failures.
 *
 * Lives in gitignored node_modules, so nothing here enters the repo and any real
 * `bun install` replaces it.
 *
 * Deliberately NOT a full reimplementation. Everything the callers use is here and
 * anything else THROWS rather than quietly returning a wrong answer — a shim that
 * silently no-ops is what made the empty stub dangerous.
 */
"use strict";

const { Database: BunDatabase } = require("bun:sqlite");

class Statement {
	constructor(inner, sql) {
		this._inner = inner;
		this._sql = sql;
		this._raw = false;
		this._pluck = false;
	}

	get source() {
		return this._sql;
	}

	// better-sqlite3 takes bind params as varargs or a single object; Bun's
	// accepts the same two shapes, so they pass straight through.
	all(...params) {
		if (this._raw) return this._inner.values(...params);
		const rows = this._inner.all(...params);
		if (this._pluck) {
			return rows.map((row) => row[Object.keys(row)[0]]);
		}
		return rows;
	}

	get(...params) {
		if (this._raw) {
			const rows = this._inner.values(...params);
			return rows.length > 0 ? rows[0] : undefined;
		}
		const row = this._inner.get(...params);
		if (row === null || row === undefined) return undefined;
		if (this._pluck) return row[Object.keys(row)[0]];
		return row;
	}

	run(...params) {
		const result = this._inner.run(...params);
		// better-sqlite3 guarantees these two fields; Bun returns them under the
		// same names, but normalise so a caller reading `changes` never sees
		// undefined and mistakes "no rows matched" for "column missing".
		return {
			changes: result?.changes ?? 0,
			lastInsertRowid: result?.lastInsertRowid ?? 0,
		};
	}

	values(...params) {
		return this._inner.values(...params);
	}

	*iterate(...params) {
		// Bun exposes an iterator on the statement; fall back to materialising so a
		// caller that only iterates still gets every row rather than none.
		if (typeof this._inner.iterate === "function") {
			yield* this._inner.iterate(...params);
			return;
		}
		yield* this.all(...params);
	}

	raw(enabled = true) {
		this._raw = enabled !== false;
		return this;
	}

	pluck(enabled = true) {
		this._pluck = enabled !== false;
		return this;
	}

	expand() {
		throw new Error(
			"better-sqlite3 shim: expand() is not implemented. Add it here rather than working around it.",
		);
	}

	bind() {
		throw new Error(
			"better-sqlite3 shim: bind() is not implemented; pass parameters to all/get/run instead.",
		);
	}

	safeIntegers() {
		return this;
	}

	columns() {
		return (this._inner.columnNames ?? []).map((name) => ({ name }));
	}

	finalize() {
		if (typeof this._inner.finalize === "function") this._inner.finalize();
	}
}

class Database {
	constructor(name, options = {}) {
		this.name = name;
		this.memory = name === ":memory:";
		this.readonly = options.readonly === true;
		this.open = true;
		this.inTransaction = false;
		this._db = new BunDatabase(name, {
			readonly: this.readonly,
			create: options.readonly !== true,
		});
	}

	prepare(sql) {
		return new Statement(this._db.prepare(sql), sql);
	}

	exec(sql) {
		this._db.exec(sql);
		return this;
	}

	/**
	 * better-sqlite3's pragma() runs the statement and returns rows; with
	 * `{ simple: true }` it returns the first column of the first row. Both shapes
	 * are used in this codebase, so both are honoured.
	 */
	pragma(source, options = {}) {
		const rows = this._db.prepare(`PRAGMA ${source}`).all();
		if (options.simple === true) {
			if (rows.length === 0) return undefined;
			const first = rows[0];
			return first[Object.keys(first)[0]];
		}
		return rows;
	}

	/**
	 * A real transaction, which is the whole reason this shim exists: the answer
	 * ledger's compare-and-set is only atomic if BEGIN/COMMIT actually happen.
	 *
	 * better-sqlite3 semantics: the returned function runs the body inside a
	 * transaction, commits on return, rolls back on throw, and nests via
	 * savepoints. Bun's `transaction()` provides exactly that, including the
	 * `.deferred`/`.immediate`/`.exclusive` variants callers may reach for.
	 */
	transaction(fn) {
		const wrapped = this._db.transaction((...args) => {
			this.inTransaction = true;
			try {
				return fn(...args);
			} finally {
				this.inTransaction = false;
			}
		});
		return wrapped;
	}

	close() {
		if (this.open) {
			this._db.close();
			this.open = false;
		}
		return this;
	}

	function(name, ...rest) {
		const impl = rest[rest.length - 1];
		this._db.loadExtension === undefined;
		if (typeof this._db.function === "function") {
			this._db.function(name, impl);
			return this;
		}
		throw new Error(
			`better-sqlite3 shim: custom function '${name}' is not supported by this Bun version.`,
		);
	}

	aggregate(name) {
		throw new Error(
			`better-sqlite3 shim: aggregate('${name}') is not implemented. Add it here rather than working around it.`,
		);
	}

	loadExtension(path) {
		throw new Error(
			`better-sqlite3 shim: loadExtension('${path}') is not implemented.`,
		);
	}

	backup() {
		throw new Error("better-sqlite3 shim: backup() is not implemented.");
	}

	serialize() {
		if (typeof this._db.serialize === "function") return this._db.serialize();
		throw new Error("better-sqlite3 shim: serialize() is not implemented.");
	}

	defaultSafeIntegers() {
		return this;
	}

	unsafeMode() {
		return this;
	}
}

module.exports = Database;
module.exports.default = Database;
module.exports.Database = Database;

