/**
 * tmp/ only. Proves the (ANSWER-LEDGER) fence against a REAL database.
 *
 * The headline check is the overtaking race, and it is driven deterministically
 * rather than by racing threads and hoping: the race IS the call order. A status
 * read that lands after an answer was admitted but before it claimed is exactly
 * `resolveStatus` then `claimForAnswer`, so that is what runs.
 *
 * This is testable at all only because better-sqlite3 is now shimmed over Bun's
 * SQLite (tmp/better-sqlite3-shim.js) — the previous stub answered every query
 * with nothing, so no database path had ever executed on this machine.
 */
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createDb } from "../packages/host-service/src/db";
import { createAttemptLedger } from "../packages/host-service/src/companion/attempt-ledger";
import type { RequestId, EpochMs } from "../packages/host-service/src/companion/types";

const MIGRATIONS = join(import.meta.dirname, "../packages/host-service/drizzle");
const HOUR = 3_600_000;
let failures = 0;

function check(label: string, ok: boolean, detail: string) {
	if (!ok) failures += 1;
	console.log(`${ok ? "PASS" : "FAIL"}  ${label} :: ${detail}`);
}

function freshLedger(nowMs = 1_000_000_000_000) {
	const dir = mkdtempSync(join(tmpdir(), "ledger-"));
	const db = createDb(join(dir, "host.db"), MIGRATIONS);
	const events: Record<string, unknown>[] = [];
	let clock = nowMs;
	const ledger = createAttemptLedger({
		db,
		log: (e) => events.push(e),
		now: () => clock as EpochMs,
	});
	return {
		ledger,
		events,
		setClock: (ms: number) => {
			clock = ms;
		},
		db,
	};
