52			failures += 1;
53			console.log(`FAIL ${name} ${extra}`);
54		} else {
55			console.log(`ok   ${name}`);
56		}
57	}
58	
59	const PLACEHOLDER_TOKEN = {
60		clientId: ACCESS_CLIENT_ID,
61		clientSecret: "0".repeat(64), // placeholder, never the real secret
62	};
63	
64	// ---------------------------------------------------------------------------
65	// the phone side, written from PROTOCOL.md §3.1 / §4.4 only
66	// ---------------------------------------------------------------------------
67	function phoneDerive(input: {
68		pPriv: Uint8Array;
69		dPub: Uint8Array;
70		pairingCode: Uint8Array;
71		pairSalt: Uint8Array;
72		pid: string;
73		deviceId: string;
74	}) {
75		const z = x25519(input.pPriv, input.dPub);
76		const ikm = new Uint8Array(64);
77		ikm.set(z, 0);
78		ikm.set(input.pairingCode, 32);
79		const saltPrefix = Buffer.from(PAIRING_HKDF_SALT_PREFIX, "ascii");
80		const salt = new Uint8Array(saltPrefix.length + 16);
81		salt.set(saltPrefix, 0);
82		salt.set(input.pairSalt, saltPrefix.length);
83		const prk = hkdfExtract(salt, ikm);
84		return {
85			prk,
86			// RAW BYTES, not base64url text.
87			//
88			// This probe used to derive K_dev as
89			// `hkdfExpandLabel(prk, LABEL + pid + deviceId)` — the ids as base64url TEXT
90			// concatenated into the label — and then failed at `openSealed` with
91			// `unknown_device`, because the bridge's step-4 response was sealed under a
92			// different key. It looked like a pairing bug in the bridge. It was not.
93			//
94			// crypto.ts's INTEROP NOTE records that §3.1 is ambiguous about whether the
95			// id suffixes contribute their raw bytes or their text, that both sides once
96			// declared OPPOSITE conventions (so pairing could never succeed), and that
97			// the ambiguity was resolved in favour of RAW BYTES to match the Android
98			// client's `KeyDerivation`. The bridge moved; this probe did not, so it was
99			// asserting a contract nobody implements any more.
100			//
101			// The cross-runtime differential harness
102			// (tmp/differential_vectors/run-differential.ps1) agrees bridge-to-Kotlin on
103			// pairing_response and x25519 at 154/154, which is what identifies the probe
104			// rather than the bridge as the stale side.
105			kDev: hkdfExpandInfo(
106				prk,
107				hkdfInfoWithSuffix(
108					HKDF_LABEL_DEVICE,
109					base64UrlDecode(input.pid),
110					base64UrlDecode(input.deviceId),
111				),
112				32,
113			),
114			kConfP: hkdfExpandLabel(prk, HKDF_LABEL_CONFIRM_PHONE, 32),
115			kConfD: hkdfExpandLabel(prk, HKDF_LABEL_CONFIRM_DESKTOP, 32),
116		};
117	}
118	
119	function parseQr(uri: string) {
120		const frag = uri.slice(uri.indexOf("#") + 1);
121		const params = new URLSearchParams(frag);
122		return {
123			v: params.get("v"),
124			h: params.get("h"),
125			pid: params.get("pid") as string,
126			pc: params.get("pc") as string,
127			fp: params.get("fp") as string,
128		};
129	}
130	
131	async function post(host: string, path: string, body: unknown) {
132		const res = await fetch(`http://${host}${path}`, {
133			method: "POST",
134			headers: { "content-type": "application/json" },
135			body: JSON.stringify(body),
136		});
137		const type = res.headers.get("content-type") ?? "";
138		if (type.includes("application/octet-stream")) {
139			return { status: res.status, bytes: new Uint8Array(await res.arrayBuffer()) };
140		}
141		return { status: res.status, json: await res.json() };
142	}
143	
