p = r'C:\Users\khair\Code Projects\fork-superset-windows-arm64\tmp\companion-pairing-check.ts'
s = open(p, encoding='utf-8').read()

# 1. import the anchor + key store, alongside the pairing imports.
old_imp = 'import { createDeviceStore } from "../packages/host-service/src/companion/device-store";'
new_imp = ('import { createDeviceStore } from "../packages/host-service/src/companion/device-store";\n'
           'import {\n\tcreateKeyStore,\n\topenStateAnchor,\n} from "../packages/host-service/src/companion/keys";')
assert s.count(old_imp) == 1
s = s.replace(old_imp, new_imp)

# 2. A device store now REQUIRES an anchor and a key store, and only one store may
#    own an anchor at a time, so each "restart" needs its own anchor closed after use.
helper = '''
/**
 * A device store over `dir`, built the way production builds one.
 *
 * `createDeviceStore` used to take just a directory. It now requires the state
 * anchor and the key store, because the anchor is what carries the anti-rollback
 * epoch and the index digest, and the key store is what the purge path needs to
 * wipe K_dev. This probe was still calling the one-argument form, which is the
 * third retired contract it was asserting.
 *
 * (ONE-STORE-PER-ANCHOR) forbids two stores owning one anchor, so a simulated
 * restart must close the previous anchor first — which is exactly what the real
 * teardown does.
 */
async function openDeviceStore(
\tdir: string,
\textra: Record<string, unknown> = {},
) {
\tconst anchor = await openStateAnchor(dir);
\tconst keys = createKeyStore(dir, anchor);
\tconst store = await createDeviceStore(dir, { anchor, keys, ...extra });
\treturn { anchor, keys, store };
}
'''
anchor_point = '// ---------------------------------------------------------------------------\n// the phone side, written from PROTOCOL.md §3.1 / §4.4 only'
assert s.count(anchor_point) == 1
s = s.replace(anchor_point, helper.strip() + "\n\n" + anchor_point)

# 3. Rewrite the three call sites.
a = '''	const store = await createDeviceStore(dir, {
		async onPurged(records) {
			for (const r of records) purged.push(r.deviceId);
		},
	});'''
b = '''	const opened = await openDeviceStore(dir, {
		async onPurged(records: { deviceId: string }[]) {
			for (const r of records) purged.push(r.deviceId);
		},
	});
	const store = opened.store;'''
assert s.count(a) == 1, "call site 1"
s = s.replace(a, b)

for old, new in [
    ("\tconst store2 = await createDeviceStore(dir);",
     "\tawait opened.anchor.close();\n\tconst reopened = await openDeviceStore(dir);\n\tconst store2 = reopened.store;"),
    ("\tconst store3 = await createDeviceStore(dir);",
     "\tawait reopened.anchor.close();\n\tconst reopened2 = await openDeviceStore(dir);\n\tconst store3 = reopened2.store;"),
]:
    assert s.count(old) == 1, old
    s = s.replace(old, new)

open(p, 'w', encoding='utf-8', newline='').write(s)
print("patched 3 call sites + helper + imports")
