18	// §0 primitives
19	// ---------------------------------------------------------------------------
20	
21	/** base64url, RFC 4648 §5, NO padding. Never standard base64. */
22	export type Base64Url = string;
23	
24	/** Integer milliseconds since the Unix epoch, UTC. */
25	export type EpochMs = number;
26	
27	/** Integer milliseconds. */
28	export type DurationMs = number;
