58	export type ProtocolVersion = number;
59	
60	/** §3.2 byte 0. Frozen; a mismatch is a hard `envelope_invalid`. */
61	export type EnvelopeVersion = 1;
62	
63	// ---------------------------------------------------------------------------
64	// §3 the sealed envelope
65	// ---------------------------------------------------------------------------
66	
67	/** §3.2 byte 2. */
68	export const ENVELOPE_KIND_REQUEST = 0x01;
69	export const ENVELOPE_KIND_RESPONSE = 0x02;
70	export const ENVELOPE_KIND_EVENT = 0x03;
71	
72	export type EnvelopeKind =
73		| typeof ENVELOPE_KIND_REQUEST
74		| typeof ENVELOPE_KIND_RESPONSE
75		| typeof ENVELOPE_KIND_EVENT;
76	
77	/**
78	 * The 39 cleartext header bytes of §3.2, parsed. `deviceId`/`timestampMs` are
79	 * readable before decryption on purpose (key selection + freshness); both are
80	 * inside the AAD, so editing either yields a tag failure, not a reinterpretation.
81	 */
82	export interface EnvelopeHeader {
83		version: EnvelopeVersion;
84		/** MUST be 0x00. A non-zero flags byte is `envelope_invalid`. */
85		flags: number;
