92		/** 12 raw bytes: 4-byte prefix || 8-byte big-endian counter (§3.4). */
93		nonce: Uint8Array;
94	}
95	
96	/** A parsed inbound envelope: header plus the still-sealed remainder. */
97	export interface ParsedEnvelope {
98		header: EnvelopeHeader;
99		/** Bytes [39, end) — ciphertext with the 16-byte GCM tag appended. */
100		ciphertextWithTag: Uint8Array;
