fun checkAnswerStatus(requestId: String, questionId: String, fingerprint: String) {
    viewModelScope.launch {
        // (STATUS-POLL) `in_flight` is a PENDING state, not a settled one, so this
        // keeps reading until the bridge settles it.
        //
        // It used to be one read and done. §11.5 says `in_flight` means the
        // keystrokes are landing RIGHT NOW — the bridge durably claims the request
        // before it takes the terminal lock — and §11.6 requires a pending state to
        // keep polling rather than settle. A single read landing inside the
        // injection window therefore left the sheet on "pending" until the user
        // poked it again, for an answer that confirmed a second later. The watch was
        // worse: it mapped pending to unknown and showed unconfirmed.
        //
        // BOUNDED, and every bound is deliberate:
        //  - it stops at `STATUS_POLL_DEADLINE_MS`, comfortably past the bridge's own
        //    ceiling for one sequence (a ~5 s lock wait plus a 10 s sequence
        //    deadline), so a bridge that has genuinely stopped is not polled forever;
        //  - the interval starts at `STATUS_POLL_INITIAL_MS` and backs off, because
        //    §12's read bucket is a real limit and hammering it would earn a 429 that
        //    this client correctly renders as unconfirmed — turning a resolvable
        //    answer into an unresolvable one;
        //  - it stops the moment the sheet is no longer this question, which
        //    `updateSheetIfStill` reports, so closing the sheet or opening another
        //    ends the loop instead of leaving it running against a dead target.
        //
        // Anything that is not `Pending` is terminal or honestly unknown, and both
        // settle. A read that FAILS is Unconfirmed, which settles too: retrying a
        // failed read inside this loop would be indistinguishable from retrying the
        // write, and this class exists to never do that.
        var waitMs = STATUS_POLL_INITIAL_MS
        var elapsedMs = 0L
        while (true) {
            val outcome = repository.answerStatus(requestId)
            val stillOurs = updateSheetIfStill(questionId, fingerprint) {
                it.copy(outcome = outcome)
            }
            if (!stillOurs) return@launch
            if (outcome != AnswerOutcome.Pending) return@launch
            if (elapsedMs >= STATUS_POLL_DEADLINE_MS) return@launch
            delay(waitMs)
            elapsedMs += waitMs
            waitMs = (waitMs * 2).coerceAtMost(STATUS_POLL_MAX_INTERVAL_MS)
        }
    }
}

