    /**
     * Sends a question to the watch, or [WatchQuestionOversize] if its serialised form does
     * not fit. Never a partial question: truncation is the failure this product exists to
     * prevent.
     */
    suspend fun pushQuestion(detail: QuestionDetail): WatchPushResult {
        val invalid = unrenderableReason(detail)
        if (invalid != null) {
            // The watch validates the same invariants on arrival and throws if they are
            // broken, which would crash it from its Data Layer dispatch thread. Refusing
            // here keeps the fault on the side that can see the payload.
            Log.e(TAG, "not sending ${detail.questionId} to the watch: $invalid")
            return WatchPushResult.Refused(invalid)
        }

        val question = buildQuestion(detail)
        val size = link.encodedSize(question)
        if (size > MAX_MESSAGE_BYTES) {
            val send = link.sendOversize(
                WatchQuestionOversize(
                    questionId = detail.questionId,
                    headline = question.headline,
                    itemCount = question.items.size,
                    byteSize = size,
                ),
            )
            return WatchPushResult.Oversize(send, size)
        }
        return WatchPushResult.Sent(link.sendQuestion(question))
    }

