	// The floor defaults to 8 192, so two records can never age out. Both checks were
	// therefore failing, and were being MASKED by a stale `maxEntries` call further
	// down that tripped a constructor invariant before execution ever reached here.
	// Pin the real behaviour instead: the floor protects recent records against the
	// clock, and eviction needs a record to be BOTH old and outside the floor.
	await c2.compact(now + 900_001);
	check(
		"the newest records survive a compaction past the retention (the clock cannot evict them)",
		c2.size() === 2,
		String(c2.size()),
	);
	check(
