		(await c2.admit(deviceId, nonce, now + 900_001)) === false,
	);
	await c2.close();

	// Now the same rule with a floor small enough for age to actually bite.
	const dirAged = await mkdtemp(join(tmpdir(), "sc-replay-aged-"));
	const cAged = await createReplayCache({
		noncesDir: dirAged,
		maxEntries: 8,
		minRetainedEntries: 1,
	});
	const oldNonce = randomBytes(12);
	check("aged: first admit", (await cAged.admit(deviceId, oldNonce, now)) === true);
	// A newer record, so the aged one is outside the newest-1 floor.
	await cAged.admit(deviceId, randomBytes(12), now + 1);
